SOURCE_CLAIM_JSON: {"title":"Gebremster Eifer: Staatsanwaltschaft ermittelte 1,5 Jahre gegen Scholz","publisher":"NDR","publication_date":"2022-02-23","url":"https://www.ndr.de/fernsehen/sendungen/panorama/aktuell/Gebremster-Eifer-Staatsanwaltschaft-ermittelte-15-Jahre-gegen-Scholz,cumex438.html","claim":"Hamburg prosecutors opened and held a preliminary Scholz file for about 1.5 years after 2020 complaints; an internal email from the lead prosecutor said he saw no initial suspicion and the file was later closed.","locator":"lines 63-65, 69-78","source_type":"media","source_confidence":"medium_high","source_confidence_reason":"NDR says it inspected the prosecutor file and quotes internal emails and a 36-page closing decision; still, it is a journalistic reconstruction rather than the original file.","final_evidence_use":"final_evidence","period_fit":"Directly concerns the 2020-2021 prosecutorial treatment that framed the 2022 testimony context.","ruler_attribution":"High: the file is about Scholz personally and his alleged role in the Warburg matter; attribution is direct even though the article is a secondary report.","contrary_evidence":["The full underlying file is not publicly attached here, so the exact scope of the closing reasoning cannot be independently checked from the page alone."],"lenses":["7B.2","7B.6","7B.7","7B.8"]}
